<script setup>
import {ref,onMounted} from 'vue'
import {useRouter} from 'vue-router'
import {getFeatured,getLikeStatus,toggleLike} from '../api'
import {ElMessage} from 'element-plus'
const router=useRouter(),works=ref([]),liked=ref({}),user=JSON.parse(localStorage.getItem('craft-user')||'null')
async function load(){try{works.value=(await getFeatured()).data;if(user){for(const w of works.value){try{liked.value[w.id]=(await getLikeStatus(w.id)).data.liked}catch{}}}}catch(e){console.error(e)}}
async function like(w,e){e.stopPropagation();if(!user){ElMessage.info('登录后可以点赞作品');return router.push('/login?redirect=/')}try{const{data}=await toggleLike(w.id);liked.value[w.id]=data.liked;w.likes=data.likes;ElMessage.success(data.liked?'已点赞':'已取消点赞')}catch(e){ElMessage.error(e.response?.data?.message||'操作失败')}}
onMounted(load)
</script>
<template><section class="hero"><div class="container hero-grid"><div><div class="eyebrow">HANDMADE · CUSTOM · STORY</div><h1>把你的想法，<br/>交给<em>手艺人</em>实现</h1><p>发现有温度的原创手工艺，连接创作者与喜欢独特作品的你。选一件喜欢的作品，或从一个想法开始，让它成为只属于你的实物。</p><div class="hero-actions"><button class="primary-btn" @click="$router.push('/works')">探索作品</button><button class="outline-btn" @click="$router.push('/custom')">发布定制需求</button></div></div><div class="hero-art"><img :src="works[0]?.image || '/crafts-photo/tea-set.png'" alt="手工青花茶具"/><div class="floating-note"><b>从草图到成品</b>需求 · 报价 · 制作 · 交付，全程可追踪</div></div></div></section>
<section class="section"><div class="container"><div class="section-head"><div><h2>本周精选手作</h2><p>从陶艺、木作、织染到银饰，每件作品都使用独立成品图展示。</p></div><RouterLink to="/works" class="text-link">查看全部 →</RouterLink></div><div class="work-grid"><article class="work-card clickable" v-for="w in works.slice(0,9)" :key="w.id" @click="$router.push('/works/'+w.id)"><div class="work-image"><img :src="w.image" :alt="w.title"/><span class="tag">{{w.category}}</span><button class="icon-action home-like" :class="{active:liked[w.id]}" @click="like(w,$event)">{{liked[w.id]?'♥':'♡'}} <small>{{w.likes}}</small></button></div><div class="work-body"><div class="work-title">{{w.title}}</div><p class="work-summary">{{w.summary}}</p><div class="work-meta"><span>约 {{w.leadDays}} 天制作</span><span class="price">¥{{w.price}}</span></div><div class="creator">创作者 · {{w.creatorName}}</div></div></article></div></div></section>
<section class="feature-band"><div class="container"><div class="section-head" style="margin-bottom:36px"><div><h2 style="color:white">个性定制，不止是下单</h2><p style="color:#c7bfb7">把模糊想法变成清晰方案，再把方案变成作品。</p></div></div><div class="steps"><div class="step"><span class="step-no">STEP 01</span><h3>发布需求</h3><p>填写品类、预算、材质、尺寸和期望完成时间。</p></div><div class="step"><span class="step-no">STEP 02</span><h3>创作者报价</h3><p>不同创作者给出制作方案、周期和价格。</p></div><div class="step"><span class="step-no">STEP 03</span><h3>确认制作</h3><p>选择满意方案生成订单，制作过程持续更新。</p></div><div class="step"><span class="step-no">STEP 04</span><h3>完成交付</h3><p>查看成品、确认完成并留下真实评价。</p></div></div></div></section></template>